static mut DATA: u64 = 0;
static READY: AtomicBool = AtomicBool::new(false);

fn main() {
    thread::spawn(|| {
        unsafe { DATA = 123 };            // plain, non-atomic write
        READY.store(true, Release);      // publish
    });
    while !READY.load(Acquire) {         // wait for the publish
        thread::sleep(Duration::from_millis(100));
    }
    println!("{}", unsafe { DATA });   // always prints 123
}

fn get_data() -> &'static Data {
    static PTR: AtomicPtr<Data> = AtomicPtr::new(null_mut());
    let mut p = PTR.load(Acquire);
    if p.is_null() {
        p = Box::into_raw(Box::new(generate_data()));
        if let Err(e) = PTR.compare_exchange(
            null_mut(), p, Release, Acquire  // success, failure
        ) {
            drop(unsafe { Box::from_raw(p) }); // lost the race
            p = e;                            // use the winner's pointer
        }
    }
    unsafe { &*p }
}

// Arc<T>::drop, simplified from Rust's alloc library
fn drop(&mut self) {
    let old = self.inner().strong
        .fetch_sub(1, Release);
    if old != 1 {
        return;              // other owners remain
    }
    fence(Acquire);
    unsafe { self.drop_slow() }; // destroy the data
}
